import React from 'react';
import { Link } from 'react-router-dom';

function Navbar({ user, cart = [], onLogout }) {
    const cartCount = cart.reduce((count, item) => count + item.quantity, 0);

    return (
        <nav className="navbar bg-green-600 shadow-md text-white">
            <div className="container mx-auto flex justify-between items-center py-4 px-6">
                {/* Logo Section */}
                <div className="flex items-center">
                    <Link
                        to="/"
                        className="text-2xl font-bold whitespace-nowrap hover:text-gray-200 transition"
                    >
                        MyShop
                    </Link>
                </div>

                {/* Navigation Links */}
                <div className="nav-links flex items-center space-x-6">
                    {/* Cart Section */}
                    <Link
                        to="/cart"
                        className="relative text-lg font-semibold hover:text-gray-200 transition flex items-center"
                    >
                        Cart
                        {cartCount > 0 && (
                            <span className="ml-1 bg-red-500 text-white text-xs font-bold rounded-full px-2 py-0.5">
                                {cartCount}
                            </span>
                        )}
                    </Link>

                    {/* User Section */}
                    {user ? (
                        <div className="flex items-center space-x-4">
                            {/* Orders Link */}
                            <Link
                                to="/orders"
                                className="text-lg font-semibold hover:text-gray-200 transition"
                            >
                                Orders
                            </Link>
                            {/* Greeting and Logout */}
                            <span className="font-medium whitespace-nowrap">
                                Hello, <span className="font-bold">{user.name}</span>
                            </span>
                            <button
                                onClick={onLogout}
                                className="bg-red-500 text-white px-4 py-1 rounded-md hover:bg-red-600 transition duration-200"
                            >
                                Logout
                            </button>
                        </div>
                    ) : (
                        <Link
                            to="/login"
                            className="bg-white text-green-600 px-4 py-1 rounded-md hover:bg-green-700 hover:text-white transition duration-200"
                        >
                            Login
                        </Link>
                    )}
                </div>
            </div>
        </nav>
    );
}

export default Navbar;
